  {cat:"desayuno",nm:"Granja M. Viader",m:["gastro","cultural"],d:"La granja de 1870 donde se inventó el Cacaolat: suizo (chocolate con nata) y melindros, en el Raval.",q:"hot chocolate churros Spain"},
  {cat:"desayuno",nm:"Granja La Pallaresa",m:["gastro","romantico"],d:"Churros con chocolate espeso en la calle Petritxol, como se ha hecho toda la vida.",q:"churros chocolate"},
  {cat:"desayuno",nm:"Federal Café (Sant Antoni)",m:["relax","gastro"],d:"Brunch tranquilo con terraza en la azotea, a dos calles del mercado de Sant Antoni.",q:"brunch avocado toast"},
  {cat:"desayuno",nm:"Forn Baluard (Barceloneta)",m:["gastro"],d:"El mejor pan de la Barceloneta: café y una pieza recién hecha antes de la playa.",q:"bakery bread croissant"},
  {cat:"desayuno",nm:"Café de l'Òpera",m:["cultural","romantico"],d:"Café modernista de 1929 en plena Rambla, frente al Liceu. Para desayunar con historia.",q:"Café de l'Òpera Barcelona"},
  {cat:"sight",nm:"Sagrada Família",m:["cultural","foto"],d:"La obra de Gaudí que lleva más de un siglo en obras. Por dentro, la luz de las vidrieras es lo que más impresiona.",q:"Sagrada Família"},
  {cat:"sight",nm:"Barri Gòtic y Catedral",m:["cultural","foto","romantico"],d:"Callejuelas medievales alrededor de la Catedral: Plaça del Rei, el puente de Bisbe y el antiguo barrio judío (el Call).",q:"Gothic Quarter, Barcelona"},
  {cat:"sight",nm:"Park Güell",m:["cultural","foto","relax"],d:"El parque de Gaudí con la escalinata del dragón y el banco de trencadís. La zona monumental va con entrada y hora.",q:"Park Güell"},
  {cat:"sight",nm:"Casa Batlló",m:["cultural","foto"],d:"La casa de los huesos y las escamas en Passeig de Gràcia. La azotea con las chimeneas es lo mejor.",q:"Casa Batlló"},
  {cat:"sight",nm:"La Pedrera (Casa Milà)",m:["cultural","foto"],d:"El edificio ondulado de Gaudí; sube a la azotea de los guerreros de piedra.",q:"Casa Milà"},
  {cat:"sight",nm:"El Born y Santa Maria del Mar",m:["cultural","romantico"],d:"La catedral del mar, gótico catalán puro, y alrededor las calles del Born: tiendas pequeñas y el Passeig del Born.",q:"Santa Maria del Mar, Barcelona"},
  {cat:"sight",nm:"Museu Picasso",m:["cultural"],d:"Cinco palacios medievales del Born con la obra de juventud de Picasso. Cierra los lunes.",q:"Museu Picasso"},
  {cat:"sight",nm:"Palau de la Música Catalana",m:["cultural","foto"],d:"Sala modernista con una claraboya de vidrio que parece un sol. Se visita con guía o yendo a un concierto.",q:"Palau de la Música Catalana"},
  {cat:"sight",nm:"MNAC y escalinata de Montjuïc",m:["cultural","foto"],d:"El Palau Nacional con el mejor románico del mundo dentro; desde la escalinata, la ciudad entera a tus pies.",q:"Museu Nacional d'Art de Catalunya"},
  {cat:"sight",nm:"Fundació Joan Miró",m:["cultural"],d:"Museo luminoso en lo alto de Montjuïc con la obra de Miró y una terraza con esculturas.",q:"Fundació Joan Miró"},
  {cat:"sight",nm:"Castell de Montjuïc",m:["aventura","foto"],d:"Fortaleza en lo alto de la montaña con vistas al puerto. Sube en el teleférico desde el Parc de Montjuïc.",q:"Montjuïc Castle"},
  {cat:"sight",nm:"Parc de la Ciutadella",m:["relax","romantico"],d:"El parque del centro: la cascada monumental, el lago con barcas y gente tocando y patinando.",q:"Parc de la Ciutadella"},
  {cat:"sight",nm:"Playa de la Barceloneta",m:["relax","aventura"],d:"La playa del barrio marinero. Pasea por el Passeig Marítim hasta el Peix de Frank Gehry.",q:"Barceloneta Beach"},
  {cat:"sight",nm:"Recinte Modernista de Sant Pau",m:["cultural","foto"],d:"El antiguo hospital de Domènech i Montaner: pabellones de cerámica y jardines. Mucha menos gente que en Gaudí.",q:"Hospital de la Santa Creu i Sant Pau"},
  {cat:"sight",nm:"Barrio de Gràcia",m:["relax","romantico"],d:"Antiguo pueblo con plazas llenas de terrazas (Plaça del Sol, de la Virreina). Aquí se vive Barcelona de barrio.",q:"Gràcia, Barcelona"},
  {cat:"sight",nm:"El Raval y el MACBA",m:["cultural","foto"],d:"Barrio multicultural; frente al MACBA patinan los skaters. Al lado, el CCCB.",q:"Museu d'Art Contemporani de Barcelona"},
  {cat:"sight",nm:"Palau Güell",m:["cultural"],d:"La primera gran obra de Gaudí, junto a la Rambla, con una azotea de chimeneas de colores. Cierra los lunes.",q:"Palau Güell"},
  {cat:"sight",nm:"CosmoCaixa",m:["cultural","aventura"],d:"El museo de la ciencia: un bosque amazónico de verdad dentro del edificio. Perfecto con niños.",q:"CosmoCaixa Barcelona"},
  {cat:"sight",nm:"Tibidabo",m:["aventura","romantico"],d:"La montaña de Barcelona: parque de atracciones antiguo, templo y la mejor vista de la ciudad. Sube en el funicular.",q:"Tibidabo"},
  {cat:"sight",nm:"Excursión a Montserrat",m:["aventura","cultural"],d:"La montaña de agujas a una hora en tren (FGC desde Plaça Espanya + cremallera). Monasterio, la Moreneta y rutas a pie.",q:"Montserrat (mountain)"},
  {cat:"comida",nm:"Mercat de la Boqueria (barras)",m:["gastro","cultural"],d:"Come en las barras del fondo, donde van los de aquí (El Quim, Pinotxo). Lo de la entrada es para turistas. Cierra los domingos.",q:"La Boqueria"},
  {cat:"comida",nm:"Can Culleretes",m:["gastro","cultural"],d:"El restaurante más antiguo de Barcelona (1786): canelones y cocina catalana de siempre.",q:"Catalan cuisine cannelloni"},
  {cat:"comida",nm:"La Cova Fumada",m:["gastro"],d:"La bodega de la Barceloneta donde nació la bomba. Solo a mediodía, sin cartel y siempre llena.",q:"Bomba (tapas)"},
  {cat:"comida",nm:"Quimet & Quimet",m:["gastro"],d:"Montaditos de conserva de autor en una bodega de pie del Poble-sec, forrada de botellas.",q:"montaditos tapas Spain"},
  {cat:"comida",nm:"Mercat de Santa Caterina",m:["gastro","cultural"],d:"El mercado del tejado de colores en el Born; dentro, el restaurante Cuines con producto del mercado. Cierra los domingos.",q:"Santa Caterina Market"},
  {cat:"comida",nm:"Cervecería Catalana",m:["gastro"],d:"Tapas y montaditos de barra en pleno Eixample, a un paso de Passeig de Gràcia. Siempre hay cola: ve a las 13:30.",q:"tapas bar Spain"},
  {cat:"comida",nm:"La Bodegueta (Rambla de Catalunya)",m:["gastro","cultural"],d:"Bodega de 1940 bajando unos escalones: bocadillos, tapas y vermut entre barricas.",q:"vermouth tapas"},
  {cat:"cena",nm:"Bar Mut",m:["gastro","romantico"],d:"Bar de producto del Eixample con pizarra que cambia cada día. Pequeño y muy de barrio bien.",q:"Spanish tapas restaurant"},
  {cat:"comida",nm:"Bar del Pla",m:["gastro"],d:"Tapas catalanas con un toque moderno en el Born; el calamar y el pa amb tomàquet, imprescindibles.",q:"pa amb tomaquet"},
  {cat:"cena",nm:"Cal Pep",m:["gastro","romantico"],d:"Barra de producto del mar en el Born: siéntate y deja que te recomienden. Reserva o ve pronto.",q:"Spanish seafood tapas"},
  {cat:"cena",nm:"El Xampanyet",m:["gastro","fiesta"],d:"Taberna de azulejos con cava de la casa y anchoas, en la calle del Museu Picasso. Ambiente de los de antes.",q:"El Xampanyet"},
  {cat:"cena",nm:"Can Solé",m:["gastro","romantico"],d:"Arroces y paella de la Barceloneta desde 1903. Para una cena de mar como toca.",q:"Paella"},
  {cat:"cena",nm:"7 Portes",m:["gastro","romantico","cultural"],d:"Restaurante de 1836 bajo los porches de Pla de Palau: arroces y camareros de chaqueta blanca.",q:"7 Portes"},
  {cat:"cena",nm:"La Pepita (Gràcia)",m:["gastro"],d:"Tapas creativas en Gràcia; deja tu firma en la pared. Muy pedido: llega pronto.",q:"tapas restaurant Barcelona"},
  {cat:"cena",nm:"La Plata",m:["gastro"],d:"Bar diminuto del Gòtic de 1945 con solo cuatro platos: pescaíto, butifarra, ensalada y anchoas. Y vino de porrón.",q:"fried fish Spain"},
  {cat:"atardecer",nm:"Bunkers del Carmel",m:["romantico","foto"],d:"Antiguas baterías antiaéreas en el Turó de la Rovira: la vista de 360º más bonita de Barcelona. Lleva algo de beber y respeta a los vecinos.",q:"Turó de la Rovira"},
  {cat:"atardecer",nm:"Mirador del Alcalde (Montjuïc)",m:["romantico","relax"],d:"Mirador ajardinado de Montjuïc sobre el puerto, mucho más tranquilo que los bunkers.",q:"Montjuïc"},
  {cat:"atardecer",nm:"Azotea de Las Arenas",m:["relax","foto"],d:"La antigua plaza de toros convertida en centro comercial: su azotea circular es un mirador gratis sobre Plaça Espanya.",q:"Arenas de Barcelona"},
  {cat:"atardecer",nm:"Terraza 360° del Barceló Raval",m:["romantico","relax","fiesta"],d:"La azotea circular del hotel cilíndrico de la Rambla del Raval: tejados de Ciutat Vella y Montjuïc al fondo, con una copa. El atardecer sin subir ninguna montaña.",q:"Barceló Raval"},
  {cat:"copas",nm:"Paradiso (Born)",m:["fiesta","romantico"],d:"El bar escondido detrás de la nevera de una pastrami bar del Born. De los mejores cócteles del mundo: ve pronto.",q:"cocktail bar"},
  {cat:"copas",nm:"Bar Marsella",m:["fiesta","cultural"],d:"Absenta en el bar más antiguo de la ciudad (1820), con polvo de siglos en las botellas. Raval puro.",q:"Bar Marsella"},
  {cat:"copas",nm:"Boadas",m:["romantico","cultural"],d:"La coctelería de 1933 al inicio de la Rambla: camareros de chaqueta y daiquiris como los de La Habana.",q:"Boadas"},
  {cat:"copas",nm:"Plaça del Sol (Gràcia)",m:["fiesta","relax"],d:"La plaza de las terrazas de Gràcia: botellines y ambiente joven hasta medianoche.",q:"Plaça del Sol Barcelona"},
  {cat:"copas",nm:"Dry Martini",m:["romantico"],d:"Templo del martini en el Eixample, con más de un millón de martinis servidos y contados.",q:"Dry martini cocktail"},
  {cat:"copas",nm:"Two Schmucks",m:["fiesta"],d:"Coctelería informal del Raval, de las más premiadas del mundo, con música alta y buen rollo.",q:"cocktail bar interior"},
  {cat:"disco",nm:"Razzmatazz",m:["fiesta"],d:"Cinco salas en una antigua nave del Poblenou: indie, electrónica, pop. Un clásico de la noche barcelonesa.",q:"Razzmatazz"},
  {cat:"disco",nm:"Sala Apolo",m:["fiesta"],d:"Sala de baile de 1943 en el Paral·lel: conciertos y, de madrugada, sesiones de club (Nitsa).",q:"Sala Apolo"},
  {cat:"disco",nm:"Jamboree",m:["fiesta"],d:"En la Plaça Reial: jazz a primera hora y hip-hop y funk de madrugada.",q:"Jamboree (Barcelona)"},
  {cat:"disco",nm:"Opium Barcelona",m:["fiesta"],d:"Club frente a la playa del Port Olímpic, con terraza y DJs internacionales. Ve arreglado.",q:"nightclub beach"},
  {cat:"disco",nm:"Marula Café",m:["fiesta"],d:"Funk, soul y música negra en un local pequeño del Gòtic. Para bailar sin pose.",q:"Marula Café"}
