Object.assign(VENUEX,{
  "Sagrada Família":{busy:"Las primeras franjas de la mañana (y a última hora con el sol de poniente en las vidrieras) son las mejores.",bring:"Hombros y rodillas cubiertos: es un templo y lo controlan en la puerta.",price:"€€€",tip:"Compra la entrada en la web oficial con 1-2 semanas; con audioguía se entiende el doble."},
  "Park Güell":{busy:"A primera hora (desde las 9:30) o a la última franja, cuando baja el sol.",bring:"Calzado cómodo: hay cuestas. Agua en verano.",price:"€€",tip:"Si vas en metro, baja en Lesseps o Vallcarca y sube por las escaleras mecánicas de la Baixada de la Glòria."},
  "Mercat de la Boqueria (barras)":{busy:"Ve antes de las 11:00 o a la hora de comer; a media mañana hay mucho turista mirando.",bring:"Ojo con la cartera: zona de carteristas.",price:"€€",tip:"Los zumos de la entrada son para turistas: come en las barras del fondo."},
  "Bunkers del Carmel":{busy:"Al atardecer se llena; los fines de semana, muchísimo.",bring:"Algo de abrigo (sopla viento) y agua.",price:"Gratis",tip:"Sube en el bus V17 o el 22 y acaba andando. Es un barrio de vecinos: nada de música alta."},
  "Alhambra y Generalife":{busy:"Pide la franja de los Palacios Nazaríes a primera hora o a última de la tarde.",bring:"La entrada y el DNI/pasaporte (los cotejan), agua y calzado cómodo.",price:"€€",tip:"Cómprala solo en la web oficial (hay muchas reventas). Si no quedan, la visita nocturna a los Palacios es mágica."},
  "Mirador de San Nicolás":{busy:"Al atardecer, lleno de gente y músicos. Por la mañana está tranquilo.",bring:"Cámara y paciencia para hacerte sitio en el muro.",price:"Gratis",tip:"Sube en el minibús C31 o C32 si no quieres hacer la cuesta."},
  "Bodegas Castañeda":{busy:"De 13:30 a 15:30 y de 21:00 a 23:00 está a tope.",bring:"Ganas de estar de pie en la barra.",price:"€",tip:"En Granada, con cada bebida te ponen una tapa gratis: ve de bar en bar."},
  "Azotea de Las Arenas":{busy:"Al atardecer hay gente, pero cabe todo el mundo: la terraza da la vuelta entera.",bring:"Nada especial.",price:"Gratis",tip:"Sube por dentro del centro comercial (escaleras mecánicas hasta la última planta) y sal a la terraza."},
  "Sacromonte y sus cuevas":{busy:"Por la tarde, antes de las zambras de la noche.",bring:"Calzado cómodo: todo son cuestas.",price:"Gratis",tip:"El Museo Cuevas del Sacromonte explica cómo se vivía en las cuevas."},
});

/* ============ GUÍA HECHA A MANO: Valencia (coordenadas comprobadas con OpenStreetMap; horarios y noches de apertura revisados en nov. 2026) ============ */
DB.valencia=[
  {cat:"desayuno",nm:"Horchatería Santa Catalina",m:["gastro","cultural"],d:"Horchata y fartons desde 1836 entre azulejos de Manises, al lado de la iglesia de Santa Catalina. En invierno, chocolate con churros.",q:"Horchata"},
  {cat:"desayuno",nm:"Horchatería El Siglo",m:["gastro"],d:"La rival de enfrente, en la misma plaza de Santa Catalina: horchata, fartons y chocolate de siempre.",q:"Horchata fartons"},
  {cat:"desayuno",nm:"Café Museu",m:["relax","cultural"],d:"Café bohemio del Carmen, con mesas de madera y gente leyendo. Para empezar el día sin prisa.",q:"cafe interior vintage"},
  {cat:"desayuno",nm:"Bluebell Coffee (Ruzafa)",m:["relax","gastro"],d:"Café de especialidad en Ruzafa: buen espresso, tostadas y bollería. Desayuno de barrio moderno.",q:"specialty coffee flat white"},
  {cat:"sight",nm:"Paseo por la Ciudad de las Artes y las Ciencias",m:["foto","cultural","aventura"],kind:"barrio",d:"Los edificios blancos de Calatrava sobre el agua: Hemisfèric, Museu de les Ciències, Umbracle y el Palau de les Arts. Pasear por fuera es gratis.",q:"City of Arts and Sciences"},
  {cat:"sight",nm:"Oceanogràfic",m:["aventura","relax"],kind:"zoo",d:"El acuario más grande de Europa: túnel de tiburones, belugas, el Ártico y el delfinario. Calcula media jornada.",q:"Oceanogràfic"},
  {cat:"sight",nm:"Catedral de Valencia y el Micalet",m:["cultural","foto"],d:"Tres puertas de tres estilos, el Santo Cáliz en una capilla y el Micalet: 207 escalones hasta la mejor vista del centro.",q:"Valencia Cathedral"},
  {cat:"sight",nm:"Lonja de la Seda",m:["cultural","foto"],d:"Patrimonio de la Humanidad: la sala de columnas retorcidas como palmeras donde se cerraban los tratos de la seda. Entrada de 2 €, gratis en domingo.",q:"Llotja de la Seda"},
  {cat:"sight",nm:"Mercado Central de Valencia",m:["gastro","cultural","foto"],d:"Mercado modernista con cúpulas de cristal y más de 900 puestos: naranjas, salazones, chufa. Ve por la mañana; cierra a las 15:00 y los domingos.",q:"Central Market, Valencia"},
  {cat:"sight",nm:"Plaza de la Virgen y la Basílica",m:["cultural","romantico","foto"],d:"La plaza más bonita del centro: la fuente del Turia, la Basílica de los Desamparados y la puerta de los Apóstoles, donde se reúne cada jueves el Tribunal de las Aguas.",q:"Plaza de la Virgen, Valencia"},
  {cat:"sight",nm:"Barrio del Carmen",m:["cultural","foto","fiesta"],d:"El barrio medieval de calles torcidas y grafitis enormes en las medianeras. De día se pasea; de noche es el centro de las copas.",q:"El Carmen, Valencia"},
  {cat:"sight",nm:"Torres de Serranos",m:["cultural","foto"],d:"La puerta gótica de la muralla, junto al antiguo cauce del Turia. Se sube a lo alto por unos 2 €.",q:"Serranos Towers"},
  {cat:"sight",nm:"Torres de Quart",m:["cultural","aventura"],d:"La otra puerta de la muralla: aún tiene en la piedra los impactos de cañón de la Guerra de la Independencia.",q:"Quart Towers"},
  {cat:"sight",nm:"Jardín del Turia",m:["relax","aventura","romantico"],d:"El antiguo cauce del río convertido en un parque de 9 km que cruza la ciudad: ideal en bici, corriendo o tumbado en el césped.",q:"Turia Gardens"},
  {cat:"sight",nm:"Palacio del Marqués de Dos Aguas (Museo de Cerámica)",m:["cultural","foto"],d:"La fachada de alabastro más barroca de España y, dentro, el Museo Nacional de Cerámica. Cierra los lunes.",q:"Palace of the Marqués de Dos Aguas"},
  {cat:"sight",nm:"Mercado de Colón",m:["gastro","foto","relax"],d:"Mercado modernista de trencadís reconvertido en sitio de vermut, horchata y terrazas, en pleno Ensanche.",q:"Mercado de Colón"},
  {cat:"sight",nm:"Estación del Norte (Valencia)",m:["foto","cultural"],d:"La estación modernista de naranjas y mosaicos. Entra al vestíbulo aunque no cojas tren: es gratis.",q:"Valencia Nord railway station"},
  {cat:"sight",nm:"Museo de Bellas Artes de Valencia",m:["cultural"],d:"Una de las mejores pinacotecas de España: Sorolla, Goya, Velázquez y los primitivos valencianos. Entrada gratis. Cierra los lunes.",q:"Museum of Fine Arts of Valencia"},
  {cat:"sight",nm:"IVAM",m:["cultural"],kind:"museo",d:"El museo de arte moderno de Valencia, con la colección de Julio González y buenas exposiciones temporales. Cierra los lunes.",q:"Institut Valencià d'Art Modern"},
  {cat:"sight",nm:"Bioparc",m:["aventura","relax"],kind:"zoo",d:"Zoo de inmersión con animales de África sin rejas a la vista: gorilas, lémures y la sabana. Perfecto con niños.",q:"Bioparc Valencia"},
  {cat:"sight",nm:"Barrio de Ruzafa",m:["gastro","relax","fiesta"],d:"El barrio de moda: mercado de barrio, cafés, tiendas pequeñas y, por la noche, la mayor concentración de bares de Valencia.",q:"Russafa"},
  {cat:"sight",nm:"El Cabanyal",m:["cultural","foto","relax"],kind:"barrio",d:"El barrio de pescadores junto al mar: casas bajas con fachadas de azulejos de colores. Piérdete por las calles paralelas a la playa.",q:"El Cabanyal"},
  {cat:"sight",nm:"Playa de la Malvarrosa",m:["relax","aventura"],d:"La playa de la ciudad, larga y ancha, con el paseo marítimo de Sorolla y Blasco Ibáñez. En tranvía desde el centro.",q:"Malva-rosa beach"},
  {cat:"sight",nm:"L'Almoina",m:["cultural"],kind:"ruinas",d:"Bajo una plaza de cristal, el origen de Valencia: la ciudad romana de Valentia, la visigoda y la árabe, una encima de otra.",q:"L'Almoina Archaeological Centre"},
  {cat:"sight",nm:"Iglesia de San Nicolás",m:["cultural","foto"],d:"La «Capilla Sixtina valenciana»: una iglesia gótica forrada de frescos barrocos de arriba abajo. Con entrada.",q:"Church of Sant Nicolau, Valencia"},
  {cat:"sight",nm:"Jardín Botánico de Valencia",m:["relax","romantico"],d:"El jardín botánico de la universidad (1802): palmeras, cactus, un umbráculo y muchos gatos. Un rato de calma a dos pasos del centro.",q:"Botanical Garden of the University of Valencia"},
  {cat:"sight",nm:"Museo Fallero",m:["cultural","foto"],d:"Los ninots que el público salvó del fuego cada año desde 1934: la mejor forma de entender las Fallas si no vas en marzo.",q:"Museu Faller de València"},
  {cat:"sight",nm:"Excursión a la Albufera y El Palmar",m:["relax","romantico","gastro","aventura"],exAt:"11:30",d:"El lago de los arrozales, a media hora en el bus 25 de la EMT: paseo en barca por los canales, paella donde nació (en El Palmar) y, si te quedas, el atardecer más famoso de Valencia.",q:"Albufera"},
  {cat:"comida",nm:"Casa Carmela",m:["gastro","cultural"],d:"Paella a la leña desde 1922 junto a la playa. La paella se come a mediodía, como hacen los valencianos: reserva y pídela al reservar.",q:"Paella valenciana"},
  {cat:"comida",nm:"La Pepica",m:["gastro","romantico"],d:"El restaurante de la playa desde 1898 (Hemingway comía aquí): arroces y vistas al paseo marítimo.",q:"paella seafood rice"},
  {cat:"comida",nm:"Central Bar (Mercado Central)",m:["gastro"],d:"La barra de Ricard Camarena dentro del Mercado Central: bocadillos y tapas con producto del mercado. Solo cuando abre el mercado.",q:"Central Market, Valencia"},
  {cat:"comida",nm:"Casa Roberto",m:["gastro"],d:"Arroces en el Ensanche desde hace décadas: paella valenciana, del senyoret y arroz negro. Clásico de comida familiar.",q:"arroz negro"},
  {cat:"comida",nm:"Restaurante Navarro",m:["gastro","cultural"],d:"Casa de arroces de 1951 a un paso de la Plaza del Ayuntamiento. Buena opción si no quieres ir hasta la playa.",q:"paella restaurant Spain"},
  {cat:"comida",nm:"Bodega La Pascuala",m:["gastro"],d:"Bodega del Cabanyal famosa por sus bocadillos enormes (el «almuerzo» valenciano) y su ambiente de bar de toda la vida.",q:"bocadillo Spain"},
  {cat:"cena",nm:"Casa Montaña",m:["gastro","romantico","cultural"],d:"Bodega de 1836 en el Cabanyal, con barricas y más de mil vinos: tapas de producto (anchoas, habitas, all i pebre). Reserva.",q:"Spanish wine tavern barrels"},
  {cat:"comida",nm:"Tasca Ángel",m:["gastro","cultural"],d:"Barra diminuta junto al Mercado Central donde llevan desde los años 40 haciendo sardinas a la plancha con un chato de vino. De pie y deprisa.",q:"grilled sardines"},
  {cat:"comida",nm:"Mercado de Ruzafa (barras)",m:["gastro","relax"],d:"El mercado del barrio de Ruzafa: menos turistas que el Central y barras dentro para comer algo con producto del día. Cierra los domingos.",q:"Russafa market"},
  {cat:"cena",nm:"Vuelve Carolina",m:["gastro","romantico"],d:"El bar de tapas de Quique Dacosta junto a la calle Colón: cocina valenciana de autor en formato barra, sin el precio de su restaurante de tres estrellas.",q:"tapas bar counter"},
  {cat:"cena",nm:"La Pilareta (Bar Pilar)",m:["gastro","fiesta"],d:"El bar del Carmen de las clóchinas y los mejillones en salsa picante desde 1917. Se pide un cubo y se tiran las conchas al cubo.",q:"mussels tapas"},
  {cat:"cena",nm:"Canalla Bistro",m:["gastro","romantico"],d:"El bistró de Ricard Camarena en Ruzafa: platos para compartir con guiños asiáticos, a precio razonable para su nivel.",q:"tapas restaurant modern"},
  {cat:"cena",nm:"Ricard Camarena",m:["gastro","romantico"],lux:true,d:"El restaurante de Ricard Camarena en la antigua fábrica de Bombas Gens: cocina valenciana de verduras con estrellas Michelin. Reserva con semanas.",q:"fine dining restaurant"},
  {cat:"atardecer",nm:"Ciudad de las Artes al atardecer",m:["romantico","foto","relax"],d:"Cuando cae el sol, los edificios blancos se vuelven rosas y se reflejan en el agua; luego se encienden las luces. La foto de Valencia.",q:"Ciudad de las Artes y las Ciencias at dusk"},
  {cat:"atardecer",nm:"Terraza del Ateneo (Plaza del Ayuntamiento)",m:["romantico","fiesta"],d:"Azotea con copas sobre la Plaza del Ayuntamiento: los tejados y cúpulas del centro al caer la tarde.",q:"rooftop bar Valencia"},
  {cat:"atardecer",nm:"La Fábrica de Hielo (Cabanyal)",m:["relax","fiesta","cultural"],d:"Antigua fábrica de hielo frente a la playa convertida en bar cultural: conciertos, vermut y luz de tarde junto al mar.",q:"beach bar Spain sunset"},
  {cat:"copas",nm:"Café de las Horas",m:["romantico","fiesta"],d:"Café barroco de terciopelo y candelabros junto a la plaza de la Virgen: aquí se pide la Agua de Valencia (cava, naranja, vodka y ginebra).",q:"Agua de Valencia cocktail"},
  {cat:"copas",nm:"Café Negrito",m:["fiesta","relax"],d:"La terraza de la plaza del Negrito, en el Carmen: gente de todas las edades y la noche que empieza aquí.",q:"terrace bar night Spain"},
  {cat:"copas",nm:"Jimmy Glass Jazz Bar",m:["romantico","cultural"],d:"Club de jazz con conciertos en directo casi cada semana en la calle Baja del Carmen.",q:"jazz club live music"},
  {cat:"copas",nm:"Ubik Café (Ruzafa)",m:["relax","cultural"],d:"Librería-café de Ruzafa: vino, cerveza y libros de segunda mano. Plan tranquilo de barrio.",q:"bookshop cafe"},
  {cat:"disco",nm:"Radio City",m:["fiesta"],d:"Mítico del Carmen desde los 80: los martes, flamenco en directo; el resto de noches, música para bailar sin pose hasta tarde.",q:"nightclub crowd"},
  {cat:"disco",nm:"Mya",m:["fiesta"],d:"El club de la Ciudad de las Artes, bajo el Umbracle: comercial y house hasta el amanecer, de jueves a sábado.",q:"nightclub lights"},
  {cat:"disco",nm:"Terraza L'Umbracle",m:["fiesta","romantico"],d:"La terraza de verano entre las palmeras del Umbracle de Calatrava: copas y DJ al aire libre. Solo en temporada de calor.",q:"L'Umbracle"}
];
