  {cat:"souvenir",nm:"Plaza Redonda",m:["souvenir","compras"],d:"La plaza circular escondida junto al Mercado Central, con puestos de encaje, abanicos y recuerdos.",q:"Plaza Redonda Valencia"},
  {cat:"foto",nm:"Puente de l'Assut de l'Or",m:["foto"],d:"El puente blanco con mástil de Calatrava sobre el Turia, junto a la Ciudad de las Artes.",q:"Assut de l'Or Bridge"}
